            bands.append((start, r))
            start = None
    if start is not None:
        bands.append((start, h))

    if len(bands) < 2:
        return [row[:] for row in grid]
    (a0, a1), (b0, b1) = bands[0], bands[-1]
    if a1 - a0 != b1 - b0:
        return [row[:] for row in grid]
