    best = None
    for shift in range(-(w - 1), w):
        errors = total = 0
        for k in range(n):
            for c in range(w):
                bc = c + shift
                if 0 <= bc < w:
                    errors += ((grid[a0 + k][c] != background) !=
                               (grid[b0 + k][bc] != background))
                    total += 1
        candidate = (errors / total, abs(shift), shift)
        if best is None or candidate < best:
            best = candidate
    shift = best[2]

    pairs = []
    a_only = b_only = 0
    for k in range(n):
        for c in range(w):
            bc = c + shift
